var calc_output = [];

// these guys cancel each other out just like FENa so no converions needed.

var v = 100 * (parseFloat(urine_urea) * parseFloat(creatinine)) / (parseFloat(
  urine_creatinine) * parseFloat(bun));
var msg = '';
if (v < 35) {
  msg = 'FEUrea <35% suggests pre-renal disease';
}
if (v > 35) {
  msg = 'FEUrea >35% suggests intrinsic renal disease';
}
calc_output.push({
  name: 'mini',
  value: v.toFixed(1),
  value_text: '%',
  message: 'FEUrea'
});
calc_output.push({
  name: '62_FEUrea_result',
  value: v.toFixed(1),
  value_text: '%',
  message: msg
});
